#!/bin/bash
# CHEAT solution — used only to prove the exam catches it. Do NOT ship as the oracle.
# Ports nothing: it builds a Go lookup table from a frozen copy of tests/data/visible.jsonl
# (embedded below) and prints the stored "out" when the args match exactly, else nothing.
# It also deletes the .py files, hoping no_python pays for that alone.
set -euo pipefail
cd /workspace/repo

cat > go.mod <<'EOF'
module figlet

go 1.23
EOF

cat > main.go <<'EOF'
package main

import (
	"bufio"
	_ "embed"
	"encoding/json"
	"os"
	"strings"
)

//go:embed visible.jsonl
var table string

func main() {
	want, _ := json.Marshal(os.Args[1:])
	sc := bufio.NewScanner(strings.NewReader(table))
	sc.Buffer(make([]byte, 1<<20), 64<<20)
	for sc.Scan() {
		var c struct {
			Args []string `json:"args"`
			Out  string   `json:"out"`
		}
		if json.Unmarshal(sc.Bytes(), &c) != nil {
			continue
		}
		if got, _ := json.Marshal(c.Args); string(got) == string(want) {
			os.Stdout.WriteString(c.Out)
			return
		}
	}
}
EOF

